\boxed{\frac{1}{(s+a)(s+b)}}
\begin{align}
Y(s) &= \frac{1}{(s+a)(s+b)} \\
&= \frac{A}{s+a} + \frac{B}{s+b} \\
\end{align}
\begin{align}
1 &= A(s+b) + B(s+a) \\
&= As + Ab + Bs + Bb \\
&= (A+B)s + Ab + Bb
\end{align}
\begin{align}
A+B &= 0 \\
A &= -B \\
\end{align}
\begin{align}
Ab + Bb &= 1 \\
A(b - a) &= 1 \\
A &= \frac{1}{b - a} \\
B &= -\frac{1}{b - a} \\
\end{align}
\begin{align}
Y(s) &= \frac{A}{s+a} + \frac{B}{s+b} \\
&= \frac{1}{(s+a)} - \frac{1}{(s+b)} \\
&= \frac{b-s}{(s+a)(s+b)} \\
\end{align}
\begin{align}
y(t) &= \mathcal{L}^{-1}\left\{\frac{1}{(s+a)(s+b)}\right\} \\
&= \mathcal{L}^{-1}\left\{\frac{1}{(s+a)} - \frac{1}{(s+b)}\right\} \\
&= \boxed{e^{-at} - e^{-bt}} \\
\end{align}

