.getElementsByTagName('body').item(0).style.backgroundImage = 'url("https://cdn.pixabay.com/photo/2015/10/06/22/37/road-999724_960_720.jpg")';
// 이동할 위치를 계산하는 함수
function calculateMovePosition() {
    const mousePosition = { x: 0, y: 0 };
    const position = { x: 0, y: 0 };

    const canvas = document.getElementById("myCanvas");
    const context = canvas.getContext('2d');

    // 마우스 포인터 위치를 가져오는 함수
    const getMousePosition = (event) => {
        const rect = canvas.getBoundingClientRect();
        return {
            x: event.clientX - rect.left,
            y: event.clientY - rect.top
        };
    };

    // 마우스 이동에 따라 이동할 위치 계산
    const calculateMove = (mousePosition, position) => {
        const dx = mousePosition.x - position.x;
        const dy = mousePosition.y - position.y;

        // 이동 거리와 각도 계산
        const distance = Math.sqrt(dx * dx + dy * dy);
        const angle = Math.atan2(dy, dx);

        return {
            x: position.x + Math.cos(angle) * distance,
            y: position.y + Math.sin(angle) * distance
        };
    };

    // 마우스 이벤트를 처리하는 함수
    const onMouseMove = (event) => {
        const mousePosition = getMousePosition(event);
        const movePosition = calculateMove(mousePosition, position);
        context.clearRect(0, 0, canvas.width, canvas.height);
        context.drawImage(image, 0, 0, canvas.width, canvas.height);
        context.fillText(position.x, 10, 20);
        context.fillText(movePosition.x, 10, 50);
        context.fillText(movePosition.y, 10, 80);
        position.x = movePosition.x;
        position.y = movePosition.y;
    };

    // 이벤트 리스너 추가
    canvas.addEventListener('mousemove', onMouseMove);
}

// 이동할 위치를 계산하는 함수 호출
calculateMovePosition();

// 이벤트 리스너를 제거하는 함수
const removeEventListeners = () => {
    const canvas = document.getElementById("myCanvas");
    canvas.removeEventListener('mousemove', onMouseMove);
};

// 이벤트 리스너를 제거하는 버튼 클릭 시 호출
document.getElementById("removeButton").addEventListener('click', removeEventListeners);

