import { createApp } from 'vue';
import App from './App.vue';
import Vue from 'vue';
import { createPinia } from 'pinia';

const app = createApp(App);
app.use(createPinia());
app.mount('#app');

function solveEulerEquation(x, y, y_prime) {
    const dy_dx = (y_prime * x) / y;
    return dy_dx;
}

function eulerMethod(x0, y0, h, n) {
    const x_values = [];
    const y_values = [];
    x_values.push(x0);
    y_values.push(y0);
    let y = y0;
    for (let i = 0; i < n; i++) {
        const x = x0 + i * h;
        const y_prime = solveEulerEquation(x, y, y_prime);
        y = y + h * y_prime;
        x_values.push(x);
        y_values.push(y);
    }
    return { x_values, y_values };
}

function plotEulerSolution(x_values, y_values) {
    const svg = d3.select("svg");
    const width = 800;
    const height = 400;
    const margin = { top: 20, right: 30, bottom: 30, left: 40 };
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;
    const radius = Math.min(innerWidth, innerHeight) / 2;
    const svgGroup = svg.append("g").attr("transform", `translate(${margin.left},${margin.top})`);

    const line = d3.line()
        .x(d => x_values[d])
        .y(d => y_values[d]);

    svgGroup.append("path")
        .datum(eulerMethod(0, 0, 0.1, 100).y_values)
        .attr("d", line)
        .attr("stroke", "blue")
        .attr("stroke-width", 2)
        .attr("fill", "none");

    const xAxis = d3.axisBottom().scale(x => x).ticks(5);
    svgGroup.append("g").attr("class", "x-axis").call(xAxis);

    const yAxis = d3.axisLeft().scale(y => y).ticks(5);
    svgGroup.append("g").attr("class", "y-axis").call(yAxis);

    const circle = svgGroup.selectAll("circle")
        .data(eulerMethod(0, 0, 0.1, 100).y_values)
        .enter()
        .append("circle")
        .attr("cx", x => x)
        .attr("cy", y => y)
        .attr("r", 3)
        .attr("fill", "red");

    circle.transition()
        .duration(500)
        .attr("cx", x => x + 10)
        .attr("cy", y => y + 10);

    return svg;
}

function updateEulerSolution(x0, y0, h, n) {
    const { x_values, y_values } = eulerMethod(x0, y0, h, n);
    const svg = plotEulerSolution(x_values, y_values);
    return svg;
}

function animateEulerSolution(x0, y0, h, n) {
    const svg = updateEulerSolution(x0, y0, h, n);
    svg.transition().duration(5000).style("opacity", 1);
    svg.on("click", () => {
        const svg = d3.select("svg");
        svg.style("cursor", "pointer").transition().duration(500).style("opacity", 0);
    });
}

